package rhino.optimizer;

import java.lang.reflect.Constructor;
import rhino.JSCode;
import rhino.ScriptOrFn;

/**
 * Superclass of the classes generated by {@link Codegen}. Each generated class holds the static
 * body methods of some of the scripts and functions in a compilation, and its instances are the
 * {@link JSCode} of those bodies: {@code execute} and {@code resume} switch on {@link #index} to
 * call the right one. This needs neither method handles nor a class per function.
 */
public abstract class OptJSCode<T extends ScriptOrFn<T>> extends JSCode<T> {

    /** The index of the script or function body within its compilation. */
    public final int index;

    protected OptJSCode(int index) {
        this.index = index;
    }

    /**
     * Builder environment shared by the bodies placed in one generated class. This holds whether
     * literals will need to be initialised, and the class itself once it has been defined.
     */
    public static class BuilderEnv {
        boolean hasRegExpLiterals;
        boolean hasTemplateLiterals;
        Class<?> compiledClass;
        final String className;
        private Constructor<?> constructor;

        public BuilderEnv(String className) {
            this.className = className;
        }
    }

    /**
     * A builder for {@link OptJSCode}. Holds the builder environment, names and types of the body
     * and resume methods, and the index of the body within its compilation.
     */
    public static class Builder<T extends ScriptOrFn<T>> extends JSCode.Builder<T> {
        final BuilderEnv env;
        String methodName;
        String methodType;
        String resumeName;
        int index;
        private JSCode<T> built;

        public Builder(BuilderEnv env) {
            this.env = env;
        }

        @Override
        @SuppressWarnings("unchecked")
        public JSCode<T> build() {
            if (built == null) {
                try {
                    if (env.constructor == null) {
                        env.constructor = env.compiledClass.getConstructor(int.class);
                    }
                    built = (JSCode<T>) env.constructor.newInstance(index);
                } catch (ReflectiveOperationException e) {
                    throw new IllegalStateException(e);
                }
            }
            return built;
        }
    }
}
